// нормализуем, считаем engagement velocity, фильтруем по порогу+свежести, топ-N
const minLikes = Number($('Seeds').first().json.min_likes || 1000);
const raw = items.flatMap(i => Array.isArray(i.json) ? i.json : (i.json.items || [i.json]));
const now = Date.now();
const mapped = raw.map(v => {
  const likes = v.diggCount ?? v.likesCount ?? v.likes ?? 0;
  const views = v.playCount ?? v.videoViewCount ?? v.views ?? 0;
  const created = (v.createTimeISO ? new Date(v.createTimeISO).getTime() : now);
  const ageDays = Math.max(1, (now - created) / 86400000);
  return {
    src_url: v.webVideoUrl || v.url || v.videoUrl || '',
    src_platform: v.webVideoUrl ? 'tiktok' : 'instagram',
    src_views: views, src_likes: likes,
    src_caption: (v.text || v.caption || '').slice(0, 500),
    src_velocity: Math.round(likes / ageDays),
    age_days: Math.round(ageDays)
  };
});
const kept = mapped.filter(v => v.src_likes >= minLikes && v.age_days <= 21)
  .sort((a,b) => b.src_velocity - a.src_velocity)
  .slice(0, 10);
return kept.map(json => ({ json }));

