// оставить только релевантные, собрать строку winner
const src = $('Filter winners').item.json;
let txt = $json?.content?.[0]?.text || '{}';
const m = txt.match(/\{[\s\S]*\}/); if (m) txt = m[0];
let g = {}; try { g = JSON.parse(txt); } catch(e) {}
if (!g.relevant) return [];
return [{ json: {
  id: Date.now() + '-' + Math.floor(Math.random()*1000),
  status: 'winner',
  source_type: 'clone',
  src_url: src.src_url,
  src_platform: src.src_platform,
  src_views: src.src_views,
  src_likes: src.src_likes,
  src_velocity: src.src_velocity,
  src_caption: src.src_caption,
  relevance_score: g.relevance_score ?? '',
  format_id: g.mapped_archetype ?? '',
  platforms: 'youtube,instagram,threads',
  created_at: new Date().toISOString(),
  notes: g.why ?? ''
}}];
